#pragma once

#include "duckdb/main/extension/extension_loader.hpp"

#include <cstddef>
#include <string_view>

// Each extension compiles this with its own namespace, so extensions linked into one binary
// keep separate notices; see cmake/third-party-notices.cmake.
#ifndef SIRIUS_NOTICES_NAMESPACE
#error "Define SIRIUS_NOTICES_NAMESPACE as set by sirius_notices_generate"
#endif

namespace sirius_duckdb {
inline namespace SIRIUS_NOTICES_NAMESPACE {

/// Third-party notices embedded in this extension binary. The data is generated by
/// cmake/third-party-notices.cmake.
struct third_party_notices {
  /// A byte range of document().
  struct span {
    std::size_t offset;
    std::size_t length;
  };

  /// One bundled component.
  struct row {
    char const* name;
    char const* version;   ///< Empty when unknown
    char const* license;   ///< SPDX license expression
    char const* homepage;  ///< Empty when unknown
    std::size_t text;      ///< Index of its license and notice text
  };

  /// THIRD_PARTY_NOTICES.txt: the component list followed by every distinct notice.
  static std::string_view document();
  static row const* rows_begin();
  static row const* rows_end();
  static std::string_view text(std::size_t index);

  /// Registers the sirius_licenses() table function.
  static void register_function(duckdb::ExtensionLoader& loader);
};

}  // namespace SIRIUS_NOTICES_NAMESPACE
}  // namespace sirius_duckdb
